insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  5,
  $wyb$A command-line tool that reads a raw meeting transcript - from a file or pasted text - and uses Claude (through the AI Builder credits gateway) to extract the decisions that were made, a clean list of action items with an owner and deadline for each, and a short summary, then renders all of it as a polished Markdown file you can drop straight into Notion, Slack, or a wiki page.$wyb$,
  $wyl$["Read raw text input reliably from a file or stdin, and reject empty input before it costs a credit", "Design an AI prompt using bracket markers instead of fragile JSON", "Parse a real (and a broken) AI reply without ever inventing missing information", "Normalize vague AI answers like \"TBD\" or blank into one clear default", "Render structured data into a Markdown table", "Wire multiple small files together into one command-line tool", "Call a shared AI gateway safely, with a capped max_tokens"]$wyl$::jsonb,
  $sess${"model": "Claude Haiku 4.5 (via your AI Builder credits)", "totalTime": "120 min", "buildCount": 5, "whatYouNeed": ["Your AI Builder key (Credits page on your dashboard)", "Python 3.10+ installed", "(Optional) A Google account - only needed if you try the Google Docs export idea in one of the stretch goals below"], "outcomes": ["Read a raw meeting transcript from a file or pasted text, with empty input rejected before it costs a credit", "Write a prompt that reliably extracts decisions, action items, and a summary from messy dialogue", "Parse an AI reply using bracket markers, so a missing section degrades gracefully instead of crashing", "Make sure the tool never invents a name or date the AI wasn't given - it marks those \"Unassigned\" or \"No deadline set\" instead", "Render the result as clean Markdown, including an action items table, and save it to a file", "Wire four small files into one command-line tool you can run against any transcript"], "builds": [{"number": 1, "title": "Read the raw meeting notes", "time": "15 min", "description": "Before you can format anything, you need to reliably get the transcript text into your program - from a file, or piped in directly - and reject anything too short to be worth an AI call. Get this boring part right first so nothing downstream ever receives blank input.", "steps": [{"instruction": "Create `sample_transcript.txt` - a messy, realistic meeting transcript to test with:", "prompt": "Weekly Product Sync - Sept 1\n\nAttendees: Amaka, Tunde, Chidi, Priya (dialed in late)\n\nAmaka: ok let's get started, we're behind on the onboarding redesign.\nTunde: yeah the Figma files are done, dev just hasn't picked it up yet\nChidi: I can start on it Monday if nobody else is on it\nAmaka: sounds good, go ahead Chidi\n\nAmaka: also, we need to decide on the pricing page - do we keep the\nold three-tier layout or switch to the new single-price page marketing\nsent over?\nTunde: I vote we switch, the old one is confusing people, support tickets\nabout pricing are up like 30% this month\nChidi: agreed, let's switch\nAmaka: ok, decision made - we're moving to the single-price layout\n\nPriya joins late: sorry I'm late, what did I miss\n\nAmaka: quick recap - Chidi's starting the onboarding redesign Monday,\nand we're switching the pricing page to the single-price layout\n\nTunde: one more thing, someone needs to email the beta testers about\nthe pricing change before we ship it, don't want them blindsided\nAmaka: good call\nChidi: I don't think that's on me, I'm heads down on onboarding\nTunde: I can't this week either, I'm out Thursday and Friday\nAmaka: ...ok someone needs to own that, let's figure it out after the call\n\nAmaka: last thing - can we get the pricing switch live by end of month?\nTunde: should be doable, maybe the 28th\nAmaka: let's lock the 28th as the target then\n\nPriya: quick question, are we still doing the quarterly review next week?\nAmaka: yes, same time, I'll send the invite\n\nAmaka: ok that's everything, thanks all\n", "verify": "Open the file and confirm it has multiple speakers, at least one clear decision (switching the pricing page layout), and one action item nobody clearly owns (emailing the beta testers - both Chidi and Tunde turn it down on the call). You'll use that gap to test the formatter in Build 2."}, {"instruction": "Create `notes.py` with this code:", "prompt": "\"\"\"\nStep 1 of the Meeting Notes Formatter Agent.\n\nThis file has one job: get the raw meeting transcript text, however the\nstudent wants to supply it - a file path, or pasted straight into the\nterminal (stdin). Nothing here talks to the AI; that's formatter.py.\n\"\"\"\n\nimport os\nimport sys\nimport tempfile\n\n# Stop after this many characters.\n#\n# This is a MONEY decision, not a technical one (see article.py in the\n# Social Post Generator project for the same idea). A one-hour meeting\n# transcript can run to 20,000+ characters once you include filler words\n# (\"um\", \"so\", \"yeah\") and speaker labels. The AI doesn't need every\n# \"um\" to spot the decisions and action items - 8000 characters is\n# roughly a 45-60 minute meeting's worth of substance, and sending more\n# than that mostly pays for filler, not better output.\nMAX_CHARACTERS = 8000\n\n\ndef get_transcript_text(file_path=None):\n    \"\"\"\n    Returns the raw transcript text, from a file or from stdin.\n\n        text = get_transcript_text(\"sample_transcript.txt\")\n\n    Pass no file_path (or None) to read from stdin instead - useful if\n    you want to pipe a transcript straight in:\n\n        python main.py < my_meeting.txt\n\n    Raises a clear error if the file is missing, or the transcript is\n    too short to contain anything worth formatting.\n    \"\"\"\n    if file_path:\n        try:\n            with open(file_path, \"r\", encoding=\"utf-8\") as f:\n                text = f.read()\n        except FileNotFoundError:\n            raise ValueError(\n                f\"Could not find a file at '{file_path}'.\\n\"\n                f\"Check the path is correct and try again.\"\n            )\n    else:\n        text = sys.stdin.read()\n\n    text = text.strip()\n\n    if len(text) < 20:\n        raise ValueError(\n            \"That transcript looks empty (or almost empty).\\n\"\n            \"Paste in some real meeting notes - even a few bullet points \"\n            \"of what was discussed - and try again.\"\n        )\n\n    return text[:MAX_CHARACTERS]\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check it works:  python notes.py\n    print(\"Reading sample_transcript.txt...\\n\")\n    text = get_transcript_text(\"sample_transcript.txt\")\n    print(f\"Got {len(text)} characters. First 200:\\n\")\n    print(text[:200])\n\n    print(\"\\n--- Testing a missing file path ---\")\n    try:\n        get_transcript_text(\"does_not_exist.txt\")\n        print(\"ERROR: should have raised ValueError\")\n    except ValueError as problem:\n        print(\"Correctly raised an error:\")\n        print(problem)\n\n    # A transcript with almost nothing in it (a mis-click, an empty paste)\n    # should be rejected here - with a message telling the student what\n    # to do - rather than reaching the AI and paying credits for garbage.\n    print(\"\\n--- Testing the empty-transcript guard ---\")\n    fd, tmp_path = tempfile.mkstemp(suffix=\".txt\")\n    try:\n        with os.fdopen(fd, \"w\") as f:\n            f.write(\"hi\")\n        get_transcript_text(tmp_path)\n        print(\"ERROR: should have raised ValueError\")\n    except ValueError as problem:\n        print(\"Correctly raised an error:\")\n        print(problem)\n    finally:\n        os.remove(tmp_path)\n", "verify": "Run `python notes.py`. You should see:\nReading sample_transcript.txt...\n\nGot 1535 characters. First 200:\n\nWeekly Product Sync - Sept 1...\n\n--- Testing a missing file path ---\nCorrectly raised an error:\nCould not find a file at 'does_not_exist.txt'.\nCheck the path is correct and try again.\n\n--- Testing the empty-transcript guard ---\nCorrectly raised an error:\nThat transcript looks empty (or almost empty).\nPaste in some real meeting notes - even a few bullet points of what was discussed - and try again."}], "goFurther": "Swap in a real transcript instead of the sample - copy any messy meeting notes you have (or a rough Zoom transcript export) into a new .txt file and confirm get_transcript_text() reads it exactly the same way."}, {"number": 2, "title": "Ask the AI to extract decisions, actions, and a summary", "time": "35 min", "description": "This is the heart of the project - turning a rambling transcript into decisions, action items with owners and deadlines, and a summary. It's also the one place a project like this can go quietly wrong: an AI that skips a section, or invents an owner nobody mentioned. Build the prompt and the parser together so you can prove they survive a bad reply before you ever spend a real credit on one.", "steps": [{"instruction": "Create `formatter.py` with this code:", "prompt": "\"\"\"\nStep 2 of the Meeting Notes Formatter Agent.\n\nThis file turns a raw transcript into three things the AI extracts for\nyou: the decisions that were made, the action items (each with an owner\nand a deadline), and a short summary.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n# Placeholder words the AI sometimes writes instead of just admitting a\n# field wasn't mentioned. We treat all of these the same way: \"nobody\n# said, so don't guess\" - never invent a name or a date to fill the gap.\nUNCLEAR_VALUES = {\n    \"\", \"n/a\", \"na\", \"none\", \"tbd\", \"not specified\", \"unspecified\",\n    \"unclear\", \"unknown\", \"?\", \"-\",\n}\n\n\ndef build_prompt(transcript_text):\n    \"\"\"\n    Writes the instructions we send to the AI.\n\n    The [ACTIONS] section asks for one specific plain-text shape per\n    line - \"Task: ... | Owner: ... | Deadline: ...\" - instead of JSON.\n    A stray comma in a task description, or an AI that decides to wrap\n    its reply in ```json fences, breaks a JSON parser outright. A\n    marker-based, line-by-line format degrades instead of exploding: a\n    mis-formed line just fails to match cleanly, and every other line\n    still parses fine (see _parse_action_line below).\n    \"\"\"\n    return f\"\"\"Read the meeting transcript below and extract three things.\n\nFormat your answer EXACTLY like this:\n\n[DECISIONS]\n- one decision per line, as a short plain sentence\n- if no decisions were made, write a single line: None recorded\n\n[ACTIONS]\nTask: <what needs to be done> | Owner: <who is responsible> | Deadline: <when it's due>\n(one line per action item, in that exact \"Task: ... | Owner: ... | Deadline: ...\" shape)\nIf the transcript does not clearly say who owns an item, write \"Unassigned\" as the\nOwner - do not guess a name. If no deadline was mentioned, write \"No deadline set\" as\nthe Deadline. If there are no action items at all, write a single line: None recorded\n\n[SUMMARY]\na plain 2-3 sentence summary of what the meeting was about\n\n[END]\n\nDo not add any explanation, introduction or closing remark outside these sections.\nDo not invent people, dates or decisions that are not in the transcript below.\n\nTRANSCRIPT:\n{transcript_text}\"\"\"\n\n\ndef _normalize(value, default):\n    \"\"\"A blank or vague AI answer (\"TBD\", \"N/A\", \"\") becomes one clear default.\"\"\"\n    if value.strip().lower() in UNCLEAR_VALUES:\n        return default\n    return value.strip()\n\n\ndef _parse_action_line(line):\n    \"\"\"\n    Turns one \"Task: ... | Owner: ... | Deadline: ...\" line into a dict:\n\n        {\"task\": \"Send the proposal\", \"owner\": \"Unassigned\", \"deadline\": \"No deadline set\"}\n\n    Built to survive an AI that doesn't follow the format perfectly - a\n    missing label, a missing \"|\", or a blank value all fall back to a\n    sensible default instead of raising an exception mid-run. Returns\n    None only if the line has no usable text in it at all (e.g. a\n    stray blank line inside the [ACTIONS] block).\n    \"\"\"\n    result = {\"task\": \"\", \"owner\": \"Unassigned\", \"deadline\": \"No deadline set\"}\n    leftover_text = []\n\n    for part in line.split(\"|\"):\n        part = part.strip()\n        low = part.lower()\n        if low.startswith(\"task:\"):\n            result[\"task\"] = part.split(\":\", 1)[1].strip()\n        elif low.startswith(\"owner:\"):\n            result[\"owner\"] = _normalize(part.split(\":\", 1)[1], \"Unassigned\")\n        elif low.startswith(\"deadline:\"):\n            result[\"deadline\"] = _normalize(part.split(\":\", 1)[1], \"No deadline set\")\n        elif part:\n            # No recognised label on this chunk - the AI may have skipped\n            # the \"Task:\" prefix entirely. Keep the text in case nothing\n            # else on the line turns out to carry the task description.\n            leftover_text.append(part)\n\n    if not result[\"task\"]:\n        result[\"task\"] = \" \".join(leftover_text).strip()\n\n    return result if result[\"task\"] else None\n\n\ndef parse_reply(reply):\n    \"\"\"\n    Turns the AI's one long answer into a dictionary:\n\n        {\"decisions\": [...], \"actions\": [{\"task\", \"owner\", \"deadline\"}, ...], \"summary\": \"...\"}\n\n    Mirrors generator.py's split_posts() in the Social Post Generator\n    project: [MARKER] sections we recognise are collected, anything\n    else (stray commentary, code fences) is quietly dropped instead of\n    crashing the whole program.\n    \"\"\"\n    sections = {\"DECISIONS\": [], \"ACTIONS\": [], \"SUMMARY\": []}\n    current = None\n\n    for raw_line in reply.splitlines():\n        line = raw_line.strip()\n        marker = line.strip(\"[]\").upper()\n        is_marker = line.startswith(\"[\") and line.endswith(\"]\")\n\n        # [END] tells us the sections are finished. Without it, a friendly\n        # sign-off like \"Let me know if you need changes!\" gets glued onto\n        # the summary and saved straight into the output file.\n        if is_marker and marker == \"END\":\n            break\n        if is_marker and marker in sections:\n            current = marker\n            continue\n        if current is None:\n            # Text before the first recognised marker (a stray greeting,\n            # for example) isn't part of any section - ignore it.\n            continue\n        if line.startswith(\"```\"):\n            # The AI sometimes wraps its whole answer in code fences.\n            continue\n        if line:\n            sections[current].append(line)\n\n    decisions = [\n        d.lstrip(\"-* \").strip()\n        for d in sections[\"DECISIONS\"]\n        if d.lstrip(\"-* \").strip().lower() != \"none recorded\"\n    ]\n\n    actions = []\n    for line in sections[\"ACTIONS\"]:\n        if line.strip().lower() == \"none recorded\":\n            continue\n        parsed = _parse_action_line(line)\n        if parsed:\n            actions.append(parsed)\n\n    summary = \" \".join(sections[\"SUMMARY\"]).strip()\n\n    if not decisions and not actions and not summary:\n        raise ValueError(\n            \"The AI replied, but not in the format we asked for.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    return {\"decisions\": decisions, \"actions\": actions, \"summary\": summary}\n\n\ndef format_notes(transcript_text):\n    \"\"\"\n    The main function. Give it a raw transcript, get back a parsed dict\n    ready for output.py to render.\n\n        result = format_notes(transcript_text)\n        print(result[\"summary\"])\n    \"\"\"\n    prompt = build_prompt(transcript_text)\n\n    # max_tokens caps how long the AI's answer may be, which caps what this\n    # costs you. 900 comfortably covers a summary plus a dozen action items -\n    # far more than a typical meeting produces.\n    reply = ask_ai(\n        prompt,\n        max_tokens=900,\n        project=\"meeting-notes-formatter-agent\",\n    )\n\n    return parse_reply(reply)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works, entirely\n    # offline - no AI call, no credits spent:  python formatter.py\n\n    print(\"--- Well-formed reply ---\")\n    good_reply = \"\"\"[DECISIONS]\n- Ship the v2 API on the 15th instead of the 10th\n- Drop the CSV export feature from this release\n\n[ACTIONS]\nTask: Update the release notes | Owner: Priya | Deadline: Friday\nTask: Notify the beta testers about the new date | Owner: Unassigned | Deadline: No deadline set\n\n[SUMMARY]\nThe team pushed the v2 API launch back five days to finish load testing,\nand agreed to cut CSV export from this release to protect the new date.\n\n[END]\"\"\"\n    result = parse_reply(good_reply)\n    print(f\"{len(result['decisions'])} decisions, {len(result['actions'])} actions\")\n    for action in result[\"actions\"]:\n        print(\" \", action)\n    print(\"Summary:\", result[\"summary\"])\n\n    # Now a reply an AI actually sends sometimes: no [SUMMARY] marker at\n    # all, one action item with no Owner/Deadline labels whatsoever, one\n    # with a vague \"TBD\" owner, one with no labels at all, and the whole\n    # thing wrapped in a markdown code fence. This must not crash - every\n    # gap should become a clear default, never an invented name or date.\n    print(\"\\n--- Malformed reply (missing [SUMMARY], missing/vague labels) ---\")\n    malformed_reply = \"\"\"```\n[DECISIONS]\n- Move the launch to Q3\n\n[ACTIONS]\nTask: Follow up with legal about the contract\nTask: Book the venue | Owner: TBD | Deadline: next Tuesday\nJust remember to lock the meeting room before Friday\n\n[END]\n```\"\"\"\n    result = parse_reply(malformed_reply)\n    print(f\"{len(result['decisions'])} decisions, {len(result['actions'])} actions\")\n    for action in result[\"actions\"]:\n        print(\" \", action)\n    print(\"Summary (should be blank, not crashed):\", repr(result[\"summary\"]))\n\n    # A reply with none of the markers at all - e.g. the AI ignored the\n    # instructions completely. We can't recover anything from this, so\n    # we raise a clear error instead of silently returning an empty result.\n    print(\"\\n--- Reply with no recognisable markers at all ---\")\n    try:\n        parse_reply(\"Sorry, I can't help with that request.\")\n        print(\"ERROR: should have raised ValueError\")\n    except ValueError as problem:\n        print(\"Correctly raised an error:\")\n        print(problem)\n", "verify": "Run `python formatter.py` (no AI call, no credits spent - this only tests the parsing logic against fake replies). You should see:\n--- Well-formed reply ---\n2 decisions, 2 actions\n  {'task': 'Update the release notes', 'owner': 'Priya', 'deadline': 'Friday'}\n  {'task': 'Notify the beta testers about the new date', 'owner': 'Unassigned', 'deadline': 'No deadline set'}\nSummary: The team pushed the v2 API launch back five days...\n\n--- Malformed reply (missing [SUMMARY], missing/vague labels) ---\n1 decisions, 3 actions\n  {'task': 'Follow up with legal about the contract', 'owner': 'Unassigned', 'deadline': 'No deadline set'}\n  {'task': 'Book the venue', 'owner': 'Unassigned', 'deadline': 'next Tuesday'}\n  {'task': 'Just remember to lock the meeting room before Friday', 'owner': 'Unassigned', 'deadline': 'No deadline set'}\nSummary (should be blank, not crashed): ''\n\n--- Reply with no recognisable markers at all ---\nCorrectly raised an error:\nThe AI replied, but not in the format we asked for.\nRun it again - this usually fixes itself.\nIf it keeps happening, print(reply) to see what came back."}], "goFurther": "Break it on purpose: in formatter.py's self-test, take the `malformed_reply` string and delete the `[SUMMARY]` marker AND every remaining `Owner:`/`Deadline:` label, leaving one action as a completely bare sentence with no labels at all. Run `python formatter.py` again - confirm nothing crashes, that bare-sentence action still shows up with `Unassigned` and `No deadline set`, and write a one-line comment explaining why that's safer than the AI guessing a name."}, {"number": 3, "title": "Render the result as Markdown", "time": "20 min", "description": "A Python dictionary is useless to hand a teammate. This build turns the parsed decisions/actions/summary into a Markdown document with a real table, and saves it to a timestamped file so running the tool twice never overwrites your last set of notes.", "steps": [{"instruction": "Create `output.py` with this code:", "prompt": "\"\"\"\nStep 3 of the Meeting Notes Formatter Agent.\n\nThis file turns the dictionary formatter.py produces into clean,\nreadable Markdown - either as a string to print, or as a saved .md file\nyou can drop straight into Notion, GitHub, Slack, or anywhere else that\nrenders Markdown.\n\"\"\"\n\nimport os\nfrom datetime import datetime\n\n\ndef render_markdown(parsed, title=\"Meeting Notes\"):\n    \"\"\"\n    Turns {\"decisions\": [...], \"actions\": [...], \"summary\": \"...\"} into\n    a Markdown string.\n\n        markdown = render_markdown(result)\n        print(markdown)\n\n    Works even when a section is empty - a very short transcript that\n    produced no decisions still gets a readable document with a \"no\n    decisions recorded\" line, rather than a header with nothing under it.\n    \"\"\"\n    lines = [f\"# {title}\", \"\"]\n\n    lines.append(\"## Summary\")\n    lines.append(parsed[\"summary\"] if parsed[\"summary\"] else \"_No summary available._\")\n    lines.append(\"\")\n\n    lines.append(\"## Decisions\")\n    if parsed[\"decisions\"]:\n        lines.extend(f\"- {d}\" for d in parsed[\"decisions\"])\n    else:\n        lines.append(\"_No decisions recorded._\")\n    lines.append(\"\")\n\n    lines.append(\"## Action Items\")\n    if parsed[\"actions\"]:\n        lines.append(\"| Task | Owner | Deadline |\")\n        lines.append(\"|------|-------|----------|\")\n        for action in parsed[\"actions\"]:\n            # A \"|\" inside the AI's own wording would split a Markdown\n            # table cell in two, so swap any it wrote for a dash.\n            task = action[\"task\"].replace(\"|\", \"-\")\n            owner = action[\"owner\"].replace(\"|\", \"-\")\n            deadline = action[\"deadline\"].replace(\"|\", \"-\")\n            lines.append(f\"| {task} | {owner} | {deadline} |\")\n    else:\n        lines.append(\"_No action items recorded._\")\n    lines.append(\"\")\n\n    return \"\\n\".join(lines)\n\n\ndef save_markdown(markdown_text, output_dir=\"notes_output\"):\n    \"\"\"\n    Saves markdown_text to a timestamped .md file inside output_dir\n    (created if it doesn't exist yet), and returns the path it used.\n\n        path = save_markdown(markdown)\n        print(f\"Saved to {path}\")\n\n    Timestamping the filename (instead of always writing e.g.\n    meeting_notes.md) means running this twice in a row keeps both\n    sets of notes, instead of silently overwriting the first one -\n    the exact kind of thing that's easy to miss on a Friday afternoon.\n    \"\"\"\n    os.makedirs(output_dir, exist_ok=True)\n    timestamp = datetime.now().strftime(\"%Y%m%d_%H%M%S\")\n    path = os.path.join(output_dir, f\"meeting_notes_{timestamp}.md\")\n\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(markdown_text)\n\n    return path\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check rendering and saving work,\n    # entirely offline:  python output.py\n    sample = {\n        \"decisions\": [\"Ship v2 on the 15th\", \"Drop CSV export from this release\"],\n        \"actions\": [\n            {\"task\": \"Update the release notes\", \"owner\": \"Priya\", \"deadline\": \"Friday\"},\n            {\"task\": \"Notify beta testers\", \"owner\": \"Unassigned\", \"deadline\": \"No deadline set\"},\n        ],\n        \"summary\": \"The team pushed the launch back five days to finish load testing.\",\n    }\n\n    markdown = render_markdown(sample)\n    print(markdown)\n\n    print(\"\\n--- Testing a fully empty result (nothing recorded anywhere) ---\")\n    empty = {\"decisions\": [], \"actions\": [], \"summary\": \"\"}\n    print(render_markdown(empty))\n\n    print(\"--- Saving to disk ---\")\n    saved_path = save_markdown(markdown)\n    print(f\"Saved to: {saved_path}\")\n    with open(saved_path, encoding=\"utf-8\") as f:\n        saved_content = f.read()\n    assert saved_content == markdown, \"Saved file doesn't match what we rendered!\"\n    print(\"Confirmed: saved file matches the rendered Markdown.\")\n", "verify": "Run `python output.py`. You should see the rendered Markdown printed twice (once with real sample data, once with every section empty and showing '_No summary available._' / '_No decisions recorded._' / '_No action items recorded._'), then:\n--- Saving to disk ---\nSaved to: notes_output\\meeting_notes_<timestamp>.md\nConfirmed: saved file matches the rendered Markdown.\n\nOpen the new file inside `notes_output/` and confirm the Action Items section is a real Markdown table with | Task | Owner | Deadline | columns."}], "goFurther": "Ask the AI for a fourth `[ATTENDEES]` marker in formatter.py's prompt, parse it the same way as [DECISIONS], and add an `## Attendees` section to render_markdown()."}, {"number": 4, "title": "Wire it together into one command", "time": "20 min", "description": "The last piece: one command that reads the transcript, calls the AI, and saves the result. This is also where you'll see the project's one genuinely untestable piece without a real key - the live AI call - fail with a clear message instead of a crash.", "steps": [{"instruction": "Create `main.py` with this code:", "prompt": "\"\"\"\nStep 4 of the Meeting Notes Formatter Agent - the command you actually run.\n\nRun it with:      python main.py sample_transcript.txt\nOr pipe text in:  python main.py < my_notes.txt\n\nThis wires the other three files together: read the raw notes\n(notes.py), ask the AI to pull out decisions/actions/summary\n(formatter.py), then print and save the result (output.py).\n\"\"\"\n\nimport sys\n\nfrom formatter import format_notes\nfrom notes import get_transcript_text\nfrom output import render_markdown, save_markdown\nfrom sdt_ai import AIError\n\n\ndef main():\n    file_path = sys.argv[1] if len(sys.argv) > 1 else None\n\n    try:\n        transcript_text = get_transcript_text(file_path)\n    except ValueError as problem:\n        print(f\"Could not read the transcript:\\n{problem}\")\n        sys.exit(1)\n\n    print(f\"Read {len(transcript_text)} characters. Asking the AI to format them...\\n\")\n\n    try:\n        parsed = format_notes(transcript_text)\n    except AIError as problem:\n        # sdt_ai.py writes these messages to be read directly - show them as-is.\n        print(f\"AI request failed:\\n{problem}\")\n        sys.exit(1)\n    except ValueError as problem:\n        print(f\"Could not make sense of the AI's reply:\\n{problem}\")\n        sys.exit(1)\n\n    markdown = render_markdown(parsed)\n    print(markdown)\n\n    saved_path = save_markdown(markdown)\n    print(f\"\\nSaved to: {saved_path}\")\n\n\nif __name__ == \"__main__\":\n    main()\n", "verify": "Before adding a real key, run `python main.py sample_transcript.txt`. You should see:\nRead 1535 characters. Asking the AI to format them...\n\nAI request failed:\nNo SDT_API_KEY found.\nCreate a file named .env next to your code, containing:\n    SDT_API_KEY=sdt_live_your_key_here\nCopy your key from the Credits page on your dashboard.\n\nThat confirms the whole pipeline runs cleanly up to the AI call. Now copy .env.example to .env, paste your real AI Builder key from the Credits page, and run the same command again - this time you'll get real formatted meeting notes printed and saved into notes_output/."}], "goFurther": "Stretch goal (optional - needs a Google Cloud account, not required to finish this project): write a `docs_export.py` that takes the saved Markdown file and creates a new Google Doc with the same content using the Google Docs API, returning its edit URL."}, {"number": 5, "phaseLabel": "🎯 Challenge", "title": "Challenge: Prove the no-hallucinated-owner guarantee", "time": "30 min", "description": "Anyone can wire up an API call. The real skill this project teaches is building something that doesn't quietly lie to you when the AI doesn't follow instructions perfectly. This challenge is the real test of whether you understand why the parser is built the way it is - not just whether main.py runs.", "steps": [{"instruction": "Create `challenge.py`. Write a short transcript with ONE clear action item that no speaker claims ownership of, run it through the real formatter (this is a genuine AI call and will spend a small number of credits, unlike every other self-test in this project), and check what owner comes back.", "prompt": "\"\"\"\nChallenge: prove the AI never invents an owner it wasn't given.\n\nFill in TRANSCRIPT below with 4-6 lines of meeting dialogue. Include ONE\nclear action item (e.g. \"someone needs to update the client\") but never\nsay who is doing it. This run WILL spend a small number of real AI Builder\ncredits - unlike every other self-test in this project.\n\"\"\"\n\nfrom formatter import format_notes\n\nTRANSCRIPT = \"\"\"\n# TODO: write your own 4-6 line meeting snippet here.\n\"\"\"\n\nif __name__ == \"__main__\":\n    result = format_notes(TRANSCRIPT)\n\n    for action in result[\"actions\"]:\n        print(action)\n\n    # TODO: find the action item you wrote with no stated owner and assert\n    # its \"owner\" field is exactly \"Unassigned\" - not a name you never typed.\n", "verify": "Feed it a transcript with an action item that has no stated owner. The output must mark it \"Unassigned\" - not invent a name. Concretely: after running `python challenge.py` with your real AI Builder key, at least one printed action dict must show `'owner': 'Unassigned'` exactly, and no owner name should appear anywhere in the output that wasn't literally in your TRANSCRIPT string."}]}], "portfolio": "You built a tool that turns messy, rambling meeting transcripts into clean minutes - decisions, owners, and deadlines - in seconds, and proved it doesn't hallucinate an owner when the transcript doesn't name one. Run it on a real meeting, save the Markdown output, and add it to your build portfolio.", "portfolioPrompt": "I built a Python CLI tool that takes a raw or messy meeting transcript (from a file or pasted text) and uses an AI gateway to extract decisions, action items (each with an owner and deadline), and a summary - using bracket-marker parsing so it degrades gracefully instead of crashing on a malformed AI reply, and explicitly marks missing owners as \"Unassigned\" instead of guessing.\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"}$sess$::jsonb,
  null, null,
  $tsh$[{"issue": "main.py exits immediately with \"That transcript looks empty (or almost empty)\"", "fix": "Check how you're feeding it input - a file path as the first argument, or piped text on stdin. notes.py rejects anything under 20 characters before it ever reaches the AI, so a blank paste or a typo'd path is caught here instead of wasting a credit."}, {"issue": "AI request failed: No SDT_API_KEY found", "fix": "Copy .env.example to .env in the same folder as your code, then paste your real key after the = sign: SDT_API_KEY=sdt_live_.... Copy the key itself from the Credits page on your dashboard."}, {"issue": "An action item shows \"Unassigned\" or \"No deadline set\" even though the transcript clearly named someone or a date", "fix": "This is the AI-reliability failure mode this project is built to survive: the model sometimes doesn't extract a field correctly, or phrases it in a way formatter.py's UNCLEAR_VALUES list doesn't yet recognise as blank (e.g. it writes \"the team\" instead of a name). Re-run once - it often self-corrects. If it keeps happening, print(reply) inside format_notes(), before parse_reply() runs, to see the AI's raw text and see exactly what it wrote."}, {"issue": "ValueError: \"The AI replied, but not in the format we asked for\"", "fix": "Run it again - this usually fixes itself, since it means the AI ignored the [DECISIONS]/[ACTIONS]/[SUMMARY] format entirely. If it keeps happening, check your transcript isn't longer than notes.py's MAX_CHARACTERS (8000) in a way that's cutting it off mid-sentence, which can confuse the model."}, {"issue": "The Action Items table looks broken or unaligned in the saved .md file", "fix": "Make sure you're viewing the saved file in something that renders Markdown (VS Code's preview, GitHub, Notion) rather than a plain text editor, where table syntax just looks like rows of pipe characters. output.py already replaces any literal \"|\" inside the AI's own text so it can't break the table structure itself."}]$tsh$::jsonb,
